function createHumanoid(color,isPlayer=false){const root=new THREE.Group();const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.48,.78,3,6),mat(color));torso.position.y=1.38;torso.castShadow=true;root.add(torso);const vestMesh=new THREE.Mesh(new THREE.BoxGeometry(.92,.66,.48),mat(isPlayer?0x4a6152:0x6c5143));vestMesh.position.set(0,1.42,0);root.add(vestMesh);const head=new THREE.Mesh(new THREE.SphereGeometry(.32,7,5),mat(0xd0a47c));head.position.y=2.1;head.castShadow=true;root.add(head);const helmet=new THREE.Mesh(new THREE.SphereGeometry(.35,7,4,0,Math.PI*2,0,Math.PI*.56),mat(isPlayer?0xc2d45a:0x4d6358));helmet.position.y=2.2;root.add(helmet);for(const s of [-1,1]){const leg=new THREE.Mesh(new THREE.BoxGeometry(.3,.72,.34),mat(0x384644));leg.position.set(s*.23,.47,0);root.add(leg);const arm=new THREE.Mesh(new THREE.BoxGeometry(.25,.72,.28),mat(isPlayer?0x61715b:0x59645b));arm.position.set(s*.58,1.38,0);root.add(arm);}const pack=new THREE.Mesh(new THREE.BoxGeometry(.52,.65,.25),mat(0x394a42));pack.position.set(0,1.35,-.34);root.add(pack);root.userData={torso,arms:[],legs:[]};return root;}
function createPlayer(){player={pos:new THREE.Vector3(0,groundY(0,0),0),vel:new THREE.Vector3(),yaw:Math.PI,alive:true,crouch:false,armor:0};playerModel=createHumanoid(0x526d54,true);scene.add(playerModel);const barrel=new THREE.Mesh(new THREE.BoxGeometry(.12,.12,1.2),mat(0x202c2b));barrel.position.set(.5,1.37,.35);playerModel.add(barrel);gunMesh=barrel;}
const botColors=[0x9a5844,0x596c78,0x987844,0x685c7d,0x4c7971,0x815b55];
function spawnBots(n){for(let i=0;i<n;i++){let x,z;do{x=rand(-83,83);z=rand(-83,83);}while(Math.hypot(x,z)<20);const model=createHumanoid(botColors[i%botColors.length]);model.position.set(x,groundY(x,z),z);scene.add(model);bots.push({model,pos:model.position,hp:100,alive:true,yaw:rand(-Math.PI,Math.PI),state:'wander',target:null,think:rand(0,2),shoot:rand(.8,2),speed:rand(2.4,3.8),wander:new THREE.Vector3(rand(-80,80),0,rand(-80,80)),weapon:Math.random()<.25?'SG':'AR',armor:Math.random()<.3?20:0});}}
function makeLoot(type,x,z){const group=new THREE.Group();const colors={AR:0xd8ff58,SG:0xff9d55,SR:0x77c8ff,ammo:0xe9d8a2,vest:0x64d5e0,med:0xff6d65};const color=colors[type];const shape=type==='vest'?new THREE.BoxGeometry(.65,.45,.28):type==='med'?new THREE.BoxGeometry(.48,.42,.48):new THREE.BoxGeometry(.85,.16,.22);const item=new THREE.Mesh(shape,mat(color));item.position.y=.35;item.castShadow=true;group.add(item);const glow=new THREE.Mesh(new THREE.CylinderGeometry(.42,.42,.04,12),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.6}));glow.position.y=.04;group.add(glow);group.position.set(x,groundY(x,z),z);scene.add(group);loot.push({group,type,used:false,phase:rand(0,6)});}
function spawnLoot(){const types=['AR','SG','SR','ammo','ammo','vest','med'];for(let i=0;i<34;i++){const type=types[i%types.length],a=rand(0,Math.PI*2),r=rand(9,77);makeLoot(type,Math.cos(a)*r,Math.sin(a)*r);}}
function bindInput(){window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyR')reload();if(e.code==='KeyC')toggleCrouch();if(e.code==='Space')jump();if(e.code==='Digit1')equip('AR');if(e.code==='Digit2')equip('SG');if(e.code==='Digit3')equip('SR');});window.addEventListener('keyup',e=>keys[e.code]=false);renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&running&&!dead){if(e.button===0){fireHeld=true;shoot();}if(e.button===2)mouseLook=true;}});window.addEventListener('pointerup',e=>{if(e.pointerType==='mouse'){fireHeld=false;mouseLook=false;}});renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());window.addEventListener('pointermove',e=>{if(mouseLook){camYaw-=e.movementX*.004;camPitch=clamp(camPitch+e.movementY*.003,-.08,.78);}});
$('#startBtn').onclick=()=>startGame();$('#restartBtn').onclick=()=>location.reload();$('#fireBtn').addEventListener('pointerdown',e=>{e.preventDefault();fireHeld=true;shoot();});window.addEventListener('pointerup',()=>fireHeld=false);$('#jumpBtn').addEventListener('pointerdown',e=>{e.preventDefault();jump();});$('#crouchBtn').addEventListener('pointerdown',e=>{e.preventDefault();toggleCrouch();});$('#reloadBtn').addEventListener('pointerdown',e=>{e.preventDefault();reload();});
$('#lookArea').addEventListener('pointerdown',e=>{if(e.pointerType==='touch'){e.currentTarget.setPointerCapture(e.pointerId);lookLast={x:e.clientX,y:e.clientY};}});let lookLast=null;$('#lookArea').addEventListener('pointermove',e=>{if(lookLast&&e.pointerId){camYaw-=(e.clientX-lookLast.x)*.006;camPitch=clamp(camPitch+(e.clientY-lookLast.y)*.004,-.08,.78);lookLast={x:e.clientX,y:e.clientY};}});$('#lookArea').addEventListener('pointerup',()=>lookLast=null);
const base=$('#stickBase'),knob=$('#stickKnob');base.addEventListener('pointerdown',e=>{e.preventDefault();base.setPointerCapture(e.pointerId);stick.id=e.pointerId;moveStick(e);});base.addEventListener('pointermove',e=>{if(stick.id===e.pointerId)moveStick(e);});base.addEventListener('pointerup',e=>{if(stick.id===e.pointerId){stick={x:0,y:0,id:null};knob.style.transform='translate(0,0)';}});function moveStick(e){const r=base.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=39,k=Math.min(1,max/Math.max(1,len));stick.x=dx*k/max;stick.y=dy*k/max;knob.style.transform=`translate(${dx*k}px,${dy*k}px)`;}}

