function lootDrop(x,z){makeLoot(Math.random()<.5?'ammo':Math.random()<.5?'med':'vest',x+rand(-2,2),z+rand(-2,2));}
let healRemaining=0,zoneDamageClock=0,elapsed=0;
function update(dt){if(!running||dead)return;matchTime+=dt;elapsed+=dt;fireCooldown=Math.max(0,fireCooldown-dt);if(fireHeld&&fireCooldown<=0)shoot();if(healRemaining>0){const h=Math.min(100-hp,dt*10,healRemaining*10);hp+=h;healRemaining=Math.max(0,healRemaining-dt);}
// Player movement relative to camera aim
const ix=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+stick.x,iz=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+stick.y,move=new THREE.Vector3();if(Math.abs(ix)+Math.abs(iz)>.01){const f=new THREE.Vector3(Math.sin(camYaw),0,Math.cos(camYaw)),r=new THREE.Vector3(f.z,0,-f.x);move.addScaledVector(r,ix).addScaledVector(f,-iz).normalize();const sprint=keys.ShiftLeft||keys.ShiftRight;const speed=(sprint?11:8)*(player.crouch?.43:1);player.pos.addScaledVector(move,speed*dt);playerModel.rotation.y=Math.atan2(move.x,move.z);walkT+=dt*(sprint?11:7);playerModel.children[4].rotation.x=Math.sin(walkT)*.45;playerModel.children[6].rotation.x=-Math.sin(walkT)*.45;}else{playerModel.children[4].rotation.x=0;playerModel.children[6].rotation.x=0;}
player.pos.x=clamp(player.pos.x,-105,105);player.pos.z=clamp(player.pos.z,-105,105);player.vel.y-=18*dt;player.pos.y+=player.vel.y*dt;const py=groundY(player.pos.x,player.pos.z);if(player.pos.y<py){player.pos.y=py;player.vel.y=0;}playerModel.position.copy(player.pos);playerModel.scale.y=player.crouch?.78:1;
const forward=new THREE.Vector3(Math.sin(camYaw),0,Math.cos(camYaw));const camDist=7.2;camera.position.set(player.pos.x-forward.x*camDist,player.pos.y+2.9+camPitch*2.7,player.pos.z-forward.z*camDist);camera.lookAt(player.pos.x,player.pos.y+1.45+camPitch*2,player.pos.z);
updateBots(dt);updateLoot(dt);updateZone(dt);for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.life-=dt;if(e.life<=0){scene.remove(e.obj);effects.splice(i,1);}}
if(Math.floor(elapsed)%2===0)updateMiniMap();updateHUD();const alive=bots.reduce((n,b)=>n+(b.alive?1:0),0)+1;if(alive<=1)finish(true);}
function updateBots(dt){for(const b of bots){if(!b.alive)continue;b.think-=dt;b.shoot-=dt;const toPlayer=player.pos.clone().sub(b.pos),dist=toPlayer.length();let target=null,targetDist=1e9;if(dist<46){target=player;targetDist=dist;}for(const other of bots){if(other===b||!other.alive)continue;const d=other.pos.distanceTo(b.pos);if(d<28&&d<targetDist){target=other;targetDist=d;}}
if(target&&targetDist<38){b.state=targetDist<8?'attack':'engage';const dest=target.pos.clone().sub(b.pos);if(targetDist>12){dest.y=0;dest.normalize();b.pos.addScaledVector(dest,b.speed*dt*.65);}b.yaw=Math.atan2(dest.x,dest.z);if(b.shoot<=0&&targetDist<32){b.shoot=rand(.7,1.8);if(Math.random()<.48){if(target===player){const hit=rand(7,14);damagePlayer(hit);if(hp<=0){player.alive=false;dead=true;finish(false);}}else{target.hp-=rand(8,19);if(target.hp<=0){target.alive=false;target.model.visible=false;}}}}}
else{if(b.state==='engage'||b.state==='attack')b.state='wander';if(b.think<=0||b.pos.distanceTo(b.wander)<3){b.think=rand(2,5);b.wander.set(rand(-80,80),0,rand(-80,80));}const dest=b.wander.clone().sub(b.pos);dest.y=0;if(dest.length()>1){dest.normalize();b.pos.addScaledVector(dest,b.speed*dt*.55);b.yaw=Math.atan2(dest.x,dest.z);}}
b.pos.y=groundY(b.pos.x,b.pos.z);b.model.rotation.y=b.yaw;b.model.position.copy(b.pos);
